"""Source and retrieval register for the Sushma Swaraj research workbook."""
ASOF = '2026-10-05'
sources, retrievals = [], []
def src(n, title, author, url, date, kind, locator, passage, note='', status='Passage inspected', method='web.run: page or PDF passage inspected', origin=None):
    sid=f'S{n:03d}'
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'Publication date':date,'URL':url,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ('Official record','Parliamentary record','Speech / interview','Court record') else 'Secondary','Access status':status,'Origin ID':origin or sid,'Locator':locator,'Reliability / limitation':note or 'Establishes the documented action or attributed position; not independent proof of personal causal impact.'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Canonical source or identified reproduction','access_status':status,'origin_id':origin or sid,'locator':locator,'passage_paraphrase':passage,'method':method,'result':'Relevant passage inspected' if status=='Passage inspected' else note,'next_action':'Revisit only with a better retrieval route or a new research question.'})

src(1,'Cabinet condolence resolution: Sushma Swaraj','Union Cabinet / PMO','https://www.pmindia.gov.in/en/news_updates/cabinet-condoles-death-of-former-union-cabinet-minister-smt-sushma-swaraj/','2019-08-13','Official record','Resolution, biography paragraphs','Born 14 February 1952 at Ambala; SD College graduate and Panjab University law graduate; Supreme Court practice from 1973. Haryana legislator and minister from 1977, returned in 1987. Rajya Sabha elections 1990, 2000, 2006; Lok Sabha elections 1996, 1998, 2009, 2014. I&B, Health, Parliamentary Affairs and External Affairs ministries; Leader of Opposition December 2009–May 2014. Died 6 August 2019.','Institutional obituary; praise is commemorative. Modern Haryana is used in its birthplace description; Haryana did not exist as a state in 1952.',origin='Cabinet-resolution-2019-08-13')
src(2,'Obituary reference, 7 August 2019','Rajya Sabha Secretariat','https://cms.rajyasabha.nic.in/UploadedFiles/Synopsis/SynopsisUpload/249/07082019.pdf','2019-08-07','Parliamentary record','PDF pp.1–3; printed pp.1073–1075','Rajya Sabha terms April 1990–April 1996, April 2000–April 2006, April 2006–May 2009. Four Lok Sabha elections. Participated in JP movement. First woman Delhi CM, Lok Sabha Opposition Leader and Outstanding Parliamentarian award recipient; first full-time woman EAM. Final message welcomed the Jammu and Kashmir decision.','Synopsis explicitly says it is not the authoritative verbatim debate. Honorific assessments attributed to the Chairman.')
src(3,'Sushma Swaraj: positions held','Times of India candidate profile','https://timesofindia.indiatimes.com/elections/candidates/sushma-swaraj',None,'Reference','Positions held, lines 256–260 in retrieved text','Haryana Assembly 1977–82 and 1987–90; Labour 1977–79; Education/Food/Civil Supplies 1987–90. I&B 16 May–1 June 1996; I&B and additional Telecommunications 19 March–12 October 1998; Delhi CM 13 October–3 December 1998. I&B 30 September 2000–29 January 2003; Health/Parliamentary Affairs 29 January 2003–22 May 2004. Home Affairs committee chair August 2004–2009; External Affairs committee chair 31 August 2009–1 January 2010; BJP Lok Sabha leader and Opposition Leader from 21 December 2009.','Reproduces parliamentary chronology but carries a generic, unreliable election-year disclaimer. Use historical position fields only; no financial or current-status claims. Delhi appointment day and MOIA end-date require gazette reconciliation.')
src(4,'Main RSS ki beti hoon: Idea Exchange interview','Indian Express','https://indianexpress.com/article/india/sushma-swaraj-idea-exchange-bjp-5885817/','2019-08-07','Speech / interview','Interview originally 11 February 2007; answers on Sonia Gandhi, economy and RSS','She described an RSS family background, ABVP student membership and a socialist marriage connection. Defended her 2004 threatened protest against Sonia Gandhi becoming PM as patriotic. Said growth needed inflation control; defended her Bellary campaign despite defeat.','Self-description and partisan argument, not neutral validation of claims about minorities, opponents or motives. Original 2007 interview reprinted in 2019.')
